import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.IOException;
import java.util.StringTokenizer;
import java.util.TreeSet;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        if (line == null) return;
        int n = Integer.parseInt(line.trim());

        int[] totalTime = new int[105];
        int[] lastReceived = new int[105];
        boolean[] isWaiting = new boolean[105];
        TreeSet<Integer> friends = new TreeSet<>();

        int currentTime = 0;
        int pendingDelta = 0;
        boolean firstEvent = true;

        for (int i = 0; i < n; i++) {
            line = br.readLine();
            while (line != null && line.trim().isEmpty()) {
                line = br.readLine();
            }
            if (line == null) break;

            StringTokenizer st = new StringTokenizer(line);
            String type = st.nextToken();
            int x = Integer.parseInt(st.nextToken());

            if (type.equals("T")) {
                pendingDelta = x;
            } else {
                if (firstEvent) {
                    currentTime = 0;
                    firstEvent = false;
                } else {
                    currentTime += (pendingDelta > 0) ? pendingDelta : 1;
                    pendingDelta = 0;
                }

                friends.add(x);

                if (type.equals("R")) {
                    lastReceived[x] = currentTime;
                    isWaiting[x] = true;
                } else if (type.equals("E")) {
                    totalTime[x] += currentTime - lastReceived[x];
                    isWaiting[x] = false;
                }
            }
        }

        StringBuilder sb = new StringBuilder();
        for (int friend : friends) {
            if (isWaiting[friend]) {
                sb.append(friend).append(" -1\n");
            } else {
                sb.append(friend).append(" ").append(totalTime[friend]).append("\n");
            }
        }
        System.out.print(sb);
    }
}
